package net.officefloor.hq.app;

import java.math.BigDecimal;

/**
 * What the {@code /api/invoices/all} route returns: an invoice plus the NAME of the project it is
 * for, so the one-place invoices list shows the project's name (not its id) and its lifecycle
 * status without a second lookup. Built by joining {@link Invoice} against {@link Project} in
 * {@link InvoicesAllGet}, mirroring how {@link ProjectView} carries the client's name.
 */
public class InvoiceView {

    private final Long id;
    private final Long projectId;
    private final String projectName;
    private final BigDecimal amount;
    private final String status;
    private final String issuedDate;
    private final String dueDate;

    public InvoiceView(Long id, Long projectId, String projectName, BigDecimal amount,
            String status, String issuedDate, String dueDate) {
        this.id = id;
        this.projectId = projectId;
        this.projectName = projectName;
        this.amount = amount;
        this.status = status;
        this.issuedDate = issuedDate;
        this.dueDate = dueDate;
    }

    public Long getId() {
        return id;
    }

    public Long getProjectId() {
        return projectId;
    }

    public String getProjectName() {
        return projectName;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public String getStatus() {
        return status;
    }

    public String getIssuedDate() {
        return issuedDate;
    }

    public String getDueDate() {
        return dueDate;
    }
}
===== InvoiceRepository =====
package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

/**
 * Data access for {@link Invoice}. A Spring Data bean, injected into the OfficeFloor logic classes
 * that back the /api/invoices routes.
 */
public interface InvoiceRepository extends JpaRepository<Invoice, Long> {

    /** All invoices, oldest first, so the list order is stable for the UI and tests. */
    List<Invoice> findAllByOrderByIdAsc();

    /**
     * Every invoice at one lifecycle stage, oldest first, backing the all-invoices status filter.
     * The stable oldest-first order matches {@link #findAllByOrderByIdAsc()} so filtering only
     * narrows the list, never reorders it.
     */
    List<Invoice> findByStatusOrderByIdAsc(String status);

    /**
     * All invoices, earliest due date first (id as a stable tiebreaker), backing the project
     * invoices' sort-by-due-date control.
     */
    List<Invoice> findAllByOrderByDueDateAscIdAsc();

    /**
     * The money still owed: the sum of every SENT invoice's amount, or 0 when none are sent. Only
     * invoices that have actually been sent count — a DRAFT has not gone out yet, and a PAID one has
     * already been settled — so both are excluded. Backs the dashboard's outstanding total
     * ({@code GET /api/dashboard}).
     */
    @Query("SELECT COALESCE(SUM(i.amount), 0) FROM Invoice i WHERE i.status = 'SENT'")
    BigDecimal sumSentAmount();
}
===== InvoicesGet =====
package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.web.HttpQueryParameter;
import net.officefloor.web.ObjectResponse;

/**
 * {@code GET /api/invoices} — list every invoice, oldest first, each carrying the id of the project
 * it belongs to so the project-detail view can show just its own. Wired by
 * {@code officefloor/rest/api/invoices.GET.yml}.
 *
 * <p>An optional {@code sort=due} query parameter orders the list by due date (earliest first) —
 * this backs the sort-by-due-date control on the project invoices list. Any other value (or none)
 * keeps the stable oldest-first order.
 *
 * <p>Each invoice also carries its {@code amountDue}: the amount still owed after payments (its
 * amount minus every payment recorded against it). This is derived here from the payments — not
 * stored — so the project invoices view can show how much is left to pay on each invoice.
 */
public class InvoicesGet {

    public void service(@HttpQueryParameter("sort") String sort, InvoiceRepository repository,
            PaymentRepository payments, ObjectResponse<List<Invoice>> response) {
        List<Invoice> invoices = "due".equals(sort == null ? null : sort.trim())
                ? repository.findAllByOrderByDueDateAscIdAsc()
                : repository.findAllByOrderByIdAsc();

        // Sum the payments per invoice once, then set each invoice's derived amount due (amount less
        // what has been paid) so the row shows what is still owed.
        Map<Long, BigDecimal> paidByInvoice = new HashMap<>();
        for (Payment payment : payments.findAllByOrderByIdAsc()) {
            paidByInvoice.merge(payment.getInvoiceId(), payment.getAmount(), BigDecimal::add);
        }
        for (Invoice invoice : invoices) {
            BigDecimal paid = paidByInvoice.getOrDefault(invoice.getId(), BigDecimal.ZERO);
            invoice.setAmountDue(invoice.getAmount().subtract(paid));
        }

        response.send(invoices);
    }
}
===== InvoicesAllGet =====
package net.officefloor.hq.app;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.web.HttpQueryParameter;
import net.officefloor.web.ObjectResponse;

/**
 * {@code GET /api/invoices/all} — one place listing every invoice across all projects, oldest
 * first, each carrying the NAME of the project it belongs to and its lifecycle status so the
 * all-invoices page shows the project (not its id) and the stage it is at. Wired by
 * {@code officefloor/rest/api/invoices/all.GET.yml}. Joins {@link Invoice} against {@link Project}
 * server-side, mirroring {@link ProjectsGet} joining the client's name.
 */
public class InvoicesAllGet {

    public void service(@HttpQueryParameter("status") String status, InvoiceRepository invoices,
            ProjectRepository projects, ObjectResponse<List<InvoiceView>> response) {
        Map<Long, String> nameById = projects.findAllByOrderByIdAsc().stream()
                .collect(Collectors.toMap(Project::getId, Project::getName));
        String wanted = status == null ? null : status.trim();
        List<Invoice> filtered = (wanted == null || wanted.isEmpty())
                ? invoices.findAllByOrderByIdAsc()
                : invoices.findByStatusOrderByIdAsc(wanted);
        List<InvoiceView> views = filtered.stream()
                .map(i -> new InvoiceView(i.getId(), i.getProjectId(),
                        nameById.get(i.getProjectId()), i.getAmount(), i.getStatus(),
                        i.getIssuedDate(), i.getDueDate()))
                .collect(Collectors.toList());
        response.send(views);
    }
}
